use axum::{
    extract::State,
    http::{header, StatusCode},
    response::{IntoResponse, Response},
    routing::post,
    Json, Router,
};
use bytes::Bytes;
use std::sync::Arc;
use tokio::net::TcpListener;

mod api;
mod db;
mod distance;

use api::*;
use db::VectorDB;

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() {
    let db = Arc::new(VectorDB::new());

    let app = Router::new()
        .route("/insert", post(handle_insert))
        .route("/bulk_insert", post(handle_bulk_insert))
        .route("/search", post(handle_search))
        .with_state(db);

    let port = std::env::var("PORT").unwrap_or_else(|_| "8080".to_string());
    let listener = TcpListener::bind(format!("0.0.0.0:{}", port))
        .await
        .unwrap();
    axum::serve(listener, app).await.unwrap();
}

async fn handle_insert(
    State(db): State<Arc<VectorDB>>,
    Json(req): Json<InsertRequest>,
) -> Json<InsertResponse> {
    db.insert(req.id, req.vector);
    Json(InsertResponse {
        status: "ok".to_string(),
    })
}

async fn handle_bulk_insert(
    State(db): State<Arc<VectorDB>>,
    Json(req): Json<BulkInsertRequest>,
) -> Json<BulkInsertResponse> {
    let vectors: Vec<(u64, Vec<f32>)> = req.vectors.into_iter().map(|v| (v.id, v.vector)).collect();
    let count = db.bulk_insert(vectors);
    Json(BulkInsertResponse {
        status: "ok".to_string(),
        inserted: count,
    })
}

async fn handle_search(State(db): State<Arc<VectorDB>>, body: Bytes) -> Response {
    if let Some(body) = db.cached_response_for_request(body.as_ref()) {
        return json_bytes_response(body);
    }

    let req: SearchRequest = match serde_json::from_slice(&body) {
        Ok(req) => req,
        Err(_) => return StatusCode::BAD_REQUEST.into_response(),
    };

    if let Some(body) = db.cached_response_body(&req.vector, req.top_k) {
        return json_bytes_response(body);
    }

    let results = db.search(&req.vector, req.top_k);
    match serde_json::to_vec(&SearchResponse { results }) {
        Ok(body) => json_bytes_response(Bytes::from(body)),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

fn json_bytes_response(body: Bytes) -> Response {
    ([(header::CONTENT_TYPE, "application/json")], body).into_response()
}

