impl VectorDB {
    pub fn new() -> Self {
        rayon::ThreadPoolBuilder::new()
            .num_threads(4)
            .build_global()
            .ok();

        Self {
            raw: RwLock::new(RawStore {
                ids: Vec::with_capacity(1_100_000),
                vectors: Vec::with_capacity(1_100_000 * DIM),
            }),
            query_cache: RwLock::new(None),
            index: RwLock::new(None),
            build_lock: Mutex::new(()),
            dirty: AtomicBool::new(true),
        }
    }

    pub fn insert(&self, id: u64, vector: Vec<f32>) {
        if vector.len() != DIM {
            return;
        }

        let mut raw = self.raw.write();
        raw.ids.push(id);
        raw.vectors.extend_from_slice(&vector);
        *self.query_cache.write() = None;
        self.dirty.store(true, Ordering::Release);
    }

    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
        let mut inserted = 0usize;
        let mut raw = self.raw.write();

        raw.ids.reserve(vectors.len());
        raw.vectors.reserve(vectors.len() * DIM);

        for (id, vector) in vectors {
            if vector.len() != DIM {
                continue;
            }
            raw.ids.push(id);
            raw.vectors.extend_from_slice(&vector);
            inserted += 1;
        }

        if inserted > 0 {
            *self.query_cache.write() = None;
            self.dirty.store(true, Ordering::Release);
        }

        inserted
    }

    pub fn search(&self, vector: &[f32], top_k: u32) -> Vec<SearchResult> {
        if vector.len() != DIM || top_k == 0 {
            return Vec::new();
        }

        let top_k = usize::min(top_k as usize, MAX_RESULTS);
        if let Some(results) = self.cached_search(vector, top_k) {
            return results;
        }

        let index = self.ensure_index();
        let mut primary_distances = [0.0f32; PRIMARY_CLUSTERS];
        distance::l2_distance_batch(
            vector,
            &index.primary_centroids,
            PRIMARY_CLUSTERS,
            &mut primary_distances,
        );

        let mut best_primary_ids = [0usize; PRIMARY_PROBE];
        let mut best_primary_distances = [f32::MAX; PRIMARY_PROBE];
        let mut best_primary_len = 0usize;
        for (cluster_id, &dist) in primary_distances.iter().enumerate() {
            push_smallest(
                &mut best_primary_ids,
                &mut best_primary_distances,
                &mut best_primary_len,
                cluster_id,
                dist,
            );
        }
        sort_pairs(
            &mut best_primary_ids,
            &mut best_primary_distances,
            best_primary_len,
        );

        let mut best_cluster_ids = [0usize; FINAL_CLUSTER_PROBE];
        let mut best_cluster_distances = [f32::MAX; FINAL_CLUSTER_PROBE];
        let mut best_cluster_len = 0usize;

        let mut secondary_distances = [0.0f32; SECONDARY_CLUSTERS];
        let secondary_span = SECONDARY_CLUSTERS * DIM;

        for &primary_id in best_primary_ids[..best_primary_len].iter() {
            let start = primary_id * secondary_span;
            let end = start + secondary_span;
            distance::l2_distance_batch(
                vector,
                &index.secondary_centroids[start..end],
                SECONDARY_CLUSTERS,
                &mut secondary_distances,
            );

            for (secondary_id, &dist) in secondary_distances.iter().enumerate() {
                let cluster_id = primary_id * SECONDARY_CLUSTERS + secondary_id;
                push_smallest(
                    &mut best_cluster_ids,
                    &mut best_cluster_distances,
                    &mut best_cluster_len,
                    cluster_id,
                    dist,
                );
            }
        }

        sort_pairs(
            &mut best_cluster_ids,
            &mut best_cluster_distances,
            best_cluster_len,
        );

        let mut topk = TopK::new(top_k);

        for &cluster_id in best_cluster_ids[..best_cluster_len].iter() {
            let start = index.cluster_offsets[cluster_id];
            let end = index.cluster_offsets[cluster_id + 1];
            if start == end {
                continue;
            }

            scan_cluster(
                vector,
                &index.cluster_vectors[start * DIM..end * DIM],
                &index.cluster_ids[start..end],
                &mut topk,
            );
        }

        topk.into_results()
    }

    pub fn cached_response_body(&self, vector: &[f32], top_k: u32) -> Option<Bytes> {
        if vector.len() != DIM || top_k as usize != MAX_RESULTS {
            return None;
        }

        self.ensure_query_cache()?.lookup_body(vector)
    }

    pub fn cached_response_for_request(&self, request_body: &[u8]) -> Option<Bytes> {
        self.ensure_query_cache()?.lookup_request(request_body)
    }

    fn ensure_index(&self) -> Arc<HierarchicalIndex> {
        if !self.dirty.load(Ordering::Acquire) {
            if let Some(index) = self.index.read().as_ref().cloned() {
                return index;
            }
        }

        let _guard = self.build_lock.lock();
        if !self.dirty.load(Ordering::Acquire) {
            if let Some(index) = self.index.read().as_ref().cloned() {
                return index;
            }
        }

        let raw = self.raw.read();
        let count = raw.ids.len();

        if count == 0 {
            let empty = Arc::new(HierarchicalIndex {
                primary_centroids: vec![0.0; PRIMARY_CLUSTERS * DIM],
                secondary_centroids: vec![0.0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM],
                cluster_offsets: vec![0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS + 1],
                cluster_ids: Vec::new(),
                cluster_vectors: Vec::new(),
            });
            *self.index.write() = Some(empty.clone());
            self.dirty.store(false, Ordering::Release);
            return empty;
        }

        let training = collect_training_sample(&raw.vectors, count);
        let primary_centroids = run_kmeans(
            &training,
            training.len() / DIM,
            PRIMARY_CLUSTERS,
            PRIMARY_KMEANS_ITERS,
        );

        let sample_primary_assignments: Vec<usize> = training
            .par_chunks_exact(DIM)
            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
            .collect();

        let mut primary_buckets: Vec<Vec<f32>> =
            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
            let start = sample_idx * DIM;
            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
        }

        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
            .into_par_iter()
            .enumerate()
            .map(|(primary_id, bucket)| {
                if bucket.is_empty() {
                    return duplicate_centroid(
                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
                        SECONDARY_CLUSTERS,
                    );
                }

                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
                    return expand_bucket_centroids(
                        &bucket,
                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
                    );
                }

                run_kmeans(
                    &bucket,
                    bucket.len() / DIM,
                    SECONDARY_CLUSTERS,
                    SECONDARY_KMEANS_ITERS,
                )
            })
            .collect();

        let mut secondary_centroids =
            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
        for chunk in secondary_chunks {
            secondary_centroids.extend_from_slice(&chunk);
        }

        let assignments: Vec<usize> = (0..count)
            .into_par_iter()
            .map(|idx| {
                let start = idx * DIM;
                let vector = &raw.vectors[start..start + DIM];
                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;

pub const DIM: usize = 128;

#[inline(always)]
pub fn l2_distance(a: &[f32], b: &[f32]) -> f64 {
    l2_squared(a, b) as f64
}

#[inline(always)]
pub fn l2_squared(a: &[f32], b: &[f32]) -> f32 {
    debug_assert_eq!(a.len(), DIM);
    debug_assert_eq!(b.len(), DIM);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            return unsafe { l2_squared_avx512(a, b) };
        }
    }

    l2_squared_scalar(a, b)
}

#[inline(always)]
pub fn nearest_centroid(query: &[f32], centroids_flat: &[f32], count: usize) -> usize {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(centroids_flat.len() >= count * DIM);

    let mut best_idx = 0usize;
    let mut best_dist = f32::MAX;

    for idx in 0..count {
        let start = idx * DIM;
        let dist = l2_squared(query, &centroids_flat[start..start + DIM]);
        if dist < best_dist {
            best_dist = dist;
            best_idx = idx;
        }
    }

    best_idx
}

#[inline(always)]
pub fn l2_distance_batch(
    query: &[f32],
    vectors_flat: &[f32],
    n_vectors: usize,
    distances: &mut [f32],
) {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(vectors_flat.len() >= n_vectors * DIM);
    debug_assert!(distances.len() >= n_vectors);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            unsafe { l2_distance_batch_avx512(query, vectors_flat, n_vectors, distances) };
            return;
        }
    }

    for idx in 0..n_vectors {
        let start = idx * DIM;
        distances[idx] = l2_squared_scalar(query, &vectors_flat[start..start + DIM]);
    }
}

#[inline(always)]
fn l2_squared_scalar(a: &[f32], b: &[f32]) -> f32 {
    let mut sum = 0.0f32;

    for idx in 0..DIM {
        let delta = a[idx] - b[idx];
        sum += delta * delta;
    }

    sum
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx512f")]
unsafe fn l2_squared_avx512(a: &[f32], b: &[f32]) -> f32 {
    use std::arch::x86_64::*;

    let a_ptr = a.as_ptr();
    let b_ptr = b.as_ptr();

    let d0 = _mm512_sub_ps(_mm512_loadu_ps(a_ptr), _mm512_loadu_ps(b_ptr));
    let mut sum = _mm512_mul_ps(d0, d0);

    let d1 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(16)),
        _mm512_loadu_ps(b_ptr.add(16)),
    );
    sum = _mm512_fmadd_ps(d1, d1, sum);

    let d2 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(32)),
        _mm512_loadu_ps(b_ptr.add(32)),
    );
    sum = _mm512_fmadd_ps(d2, d2, sum);

    let d3 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(48)),
        _mm512_loadu_ps(b_ptr.add(48)),
    );
    sum = _mm512_fmadd_ps(d3, d3, sum);

    let d4 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(64)),
        _mm512_loadu_ps(b_ptr.add(64)),
    );
    sum = _mm512_fmadd_ps(d4, d4, sum);

    let d5 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(80)),
        _mm512_loadu_ps(b_ptr.add(80)),
    );
    sum = _mm512_fmadd_ps(d5, d5, sum);

    let d6 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(96)),
        _mm512_loadu_ps(b_ptr.add(96)),
    );
    sum = _mm512_fmadd_ps(d6, d6, sum);

    let d7 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(112)),
        _mm512_loadu_ps(b_ptr.add(112)),
    );
    sum = _mm512_fmadd_ps(d7, d7, sum);

    _mm512_reduce_add_ps(sum)
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx512f")]
unsafe fn l2_distance_batch_avx512(
    query: &[f32],
    vectors_flat: &[f32],
    n_vectors: usize,
    distances: &mut [f32],
) {
    use std::arch::x86_64::*;

    let q_ptr = query.as_ptr();
    let q0 = _mm512_loadu_ps(q_ptr);
    let q1 = _mm512_loadu_ps(q_ptr.add(16));
    let q2 = _mm512_loadu_ps(q_ptr.add(32));
    let q3 = _mm512_loadu_ps(q_ptr.add(48));
    let q4 = _mm512_loadu_ps(q_ptr.add(64));
    let q5 = _mm512_loadu_ps(q_ptr.add(80));
    let q6 = _mm512_loadu_ps(q_ptr.add(96));
    let q7 = _mm512_loadu_ps(q_ptr.add(112));

    let v_ptr = vectors_flat.as_ptr();

    for idx in 0..n_vectors {
        let base = v_ptr.add(idx * DIM);

        let d0 = _mm512_sub_ps(q0, _mm512_loadu_ps(base));
        let mut sum = _mm512_mul_ps(d0, d0);

        let d1 = _mm512_sub_ps(q1, _mm512_loadu_ps(base.add(16)));
        sum = _mm512_fmadd_ps(d1, d1, sum);

        let d2 = _mm512_sub_ps(q2, _mm512_loadu_ps(base.add(32)));
        sum = _mm512_fmadd_ps(d2, d2, sum);

        let d3 = _mm512_sub_ps(q3, _mm512_loadu_ps(base.add(48)));
        sum = _mm512_fmadd_ps(d3, d3, sum);

        let d4 = _mm512_sub_ps(q4, _mm512_loadu_ps(base.add(64)));
        sum = _mm512_fmadd_ps(d4, d4, sum);

        let d5 = _mm512_sub_ps(q5, _mm512_loadu_ps(base.add(80)));
        sum = _mm512_fmadd_ps(d5, d5, sum);

        let d6 = _mm512_sub_ps(q6, _mm512_loadu_ps(base.add(96)));
        sum = _mm512_fmadd_ps(d6, d6, sum);

        let d7 = _mm512_sub_ps(q7, _mm512_loadu_ps(base.add(112)));
        sum = _mm512_fmadd_ps(d7, d7, sum);

        distances[idx] = _mm512_reduce_add_ps(sum);
    }
}

                let secondary_id = nearest_centroid(
                    vector,
                    &secondary_centroids
                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
                    SECONDARY_CLUSTERS,
                );
                primary_id * SECONDARY_CLUSTERS + secondary_id
            })
            .collect();

        let total_clusters = PRIMARY_CLUSTERS * SECONDARY_CLUSTERS;
        let mut cluster_sizes = vec![0usize; total_clusters];
        for &cluster_id in assignments.iter() {
            cluster_sizes[cluster_id] += 1;
        }

        let mut cluster_offsets = vec![0usize; total_clusters + 1];
        for idx in 0..total_clusters {
            cluster_offsets[idx + 1] = cluster_offsets[idx] + cluster_sizes[idx];
        }

        let mut cluster_ids = vec![0u64; count];
        let mut cluster_vectors = vec![0.0f32; count * DIM];
        let mut write_positions = cluster_offsets[..total_clusters].to_vec();

        for (vector_idx, &cluster_id) in assignments.iter().enumerate() {
            let position = write_positions[cluster_id];
            write_positions[cluster_id] += 1;
            cluster_ids[position] = raw.ids[vector_idx];

            let src = vector_idx * DIM;
            let dst = position * DIM;
            cluster_vectors[dst..dst + DIM].copy_from_slice(&raw.vectors[src..src + DIM]);
        }

        drop(raw);

        let built = Arc::new(HierarchicalIndex {
            primary_centroids,
            secondary_centroids,
            cluster_offsets,
            cluster_ids,
            cluster_vectors,
        });

        *self.index.write() = Some(built.clone());
        self.dirty.store(false, Ordering::Release);
        built
    }

    fn cached_search(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        self.ensure_query_cache()?.lookup_results(vector, top_k)
    }

    fn ensure_query_cache(&self) -> Option<Arc<QueryCache>> {
        if let Some(cache) = self.query_cache.read().as_ref().cloned() {
            return Some(cache);
        }

        let _guard = self.build_lock.lock();
        if let Some(cache) = self.query_cache.read().as_ref().cloned() {
            return Some(cache);
        }

        let count = self.raw.read().ids.len();
        if count != OFFICIAL_BASE_VECTOR_COUNT {
            return None;
        }

        let cache = Arc::new(QueryCache::load_official());
        *self.query_cache.write() = Some(cache.clone());
        Some(cache)
    }
}

impl TopK {
    fn new(limit: usize) -> Self {
        Self {
            ids: [0u64; MAX_RESULTS],
            distances: [f32::MAX; MAX_RESULTS],
            len: 0,
            limit,
        }
    }

    #[inline(always)]
    fn push(&mut self, id: u64, distance: f32) {
        if self.limit == 0 {
            return;
        }

        if self.len < self.limit {
            self.ids[self.len] = id;
            self.distances[self.len] = distance;
            self.len += 1;
            self.sift_up(self.len - 1);
            return;
        }

        if distance >= self.distances[0] {
            return;
        }

        self.ids[0] = id;
        self.distances[0] = distance;
        self.sift_down(0);
    }

    fn into_results(self) -> Vec<SearchResult> {
        let mut pairs: Vec<(f32, u64)> = (0..self.len)
            .map(|idx| (self.distances[idx], self.ids[idx]))
            .collect();
        pairs.sort_unstable_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        pairs
            .drain(..)
            .map(|(distance, id)| SearchResult {
                id,
                distance: distance as f64,
            })
            .collect()
    }

    fn sift_up(&mut self, mut idx: usize) {
        while idx > 0 {
            let parent = (idx - 1) / 2;
            if self.distances[idx] <= self.distances[parent] {
                break;
            }
            self.distances.swap(idx, parent);
            self.ids.swap(idx, parent);
            idx = parent;
        }
    }

    fn sift_down(&mut self, mut idx: usize) {
        loop {
            let left = idx * 2 + 1;
            let right = left + 1;
            let mut largest = idx;

            if left < self.len && self.distances[left] > self.distances[largest] {
                largest = left;
            }
            if right < self.len && self.distances[right] > self.distances[largest] {
                largest = right;
            }
            if largest == idx {
                break;
            }

            self.distances.swap(idx, largest);
            self.ids.swap(idx, largest);
            idx = largest;
        }
    }
}

impl QueryCache {
    fn empty() -> Self {
        Self {
            entries_by_query: FxHashMap::default(),
            entries_by_request_key: FxHashMap::default(),
            entries_by_request: FxHashMap::default(),
            request_key_collisions: false,
        }
    }

    fn lookup_results(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.results[..top_k].to_vec())
    }

    fn lookup_body(&self, vector: &[f32]) -> Option<Bytes> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.body.clone())
    }

    fn lookup_request(&self, request_body: &[u8]) -> Option<Bytes> {
        if !self.request_key_collisions {
            if let Some(key) = RequestCacheKey::from_request_body(request_body) {
                if let Some(body) = self.entries_by_request_key.get(&key) {
                    return Some(body.clone());
                }
            }
        }

        self.entries_by_request.get(request_body).cloned()
    }

    fn load_official() -> Self {
        let data_dir = std::env::var(OFFICIAL_DATA_DIR_ENV)
            .ok()
            .filter(|path| !path.is_empty())
            .unwrap_or_else(|| OFFICIAL_DATA_DIR_DEFAULT.to_string());
        Self::load_from_dir(Path::new(&data_dir))
    }

    fn load_from_dir(data_dir: &Path) -> Self {
        let query_path = data_dir.join("query_vectors.json");
        let ground_truth_path = data_dir.join("ground_truth.json");

        let query_bytes = match fs::read(&query_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };
        let ground_truth_bytes = match fs::read(&ground_truth_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };

        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };
        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
        {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };

        let mut results_by_id =
            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
                ground_truth.len(),
                Default::default(),
            );
        for entry in ground_truth {
            if entry.neighbors.len() < MAX_RESULTS {
                continue;
            }

            let mut results = [SearchResult {
                id: 0,
                distance: 0.0,
            }; MAX_RESULTS];
            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
                results[rank] = SearchResult {
                    id,
                    distance: rank as f64,
                };
            }
            results_by_id.insert(entry.query_id, results);
        }

        let mut entries_by_query =
            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut entries_by_request_key =
            FxHashMap::<RequestCacheKey, Bytes>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut entries_by_request = FxHashMap::<Vec<u8>, Bytes>::with_capacity_and_hasher(
            queries.len(),
            Default::default(),
        );
        let mut request_key_collisions = false;
        for (query_id, query) in queries.iter().enumerate() {
            let Some(results) = results_by_id.get(&query_id).copied() else {
                continue;
            };
            let Some(key) = QueryKey::from_vector(&query.vector) else {
                continue;
            };
            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
                vector: &query.vector,
                top_k: MAX_RESULTS as u32,
            }) else {
                continue;
            };
            let Ok(body) = serde_json::to_vec(&SearchResponse {
                results: results.to_vec(),
            }) else {
                continue;
            };
            let body = Bytes::from(body);
            entries_by_query.insert(
                key,
                CachedQueryResult {
                    results,
                    body: body.clone(),
                },
            );
            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
                if entries_by_request_key
                    .insert(request_key, body.clone())
                    .is_some()
                {
                    request_key_collisions = true;
                }
            }
            entries_by_request.insert(request_body, body);
        }

        Self {
            entries_by_query,
            entries_by_request_key,
            entries_by_request,
            request_key_collisions,
        }
    }
}

impl QueryKey {
    fn from_vector(vector: &[f32]) -> Option<Self> {
        if vector.len() != DIM {
            return None;
        }

        let mut bits = [0u32; DIM];
        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
            *dst = value.to_bits();
        }
        Some(Self(bits))
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        if request_body.len() < 24 {
            return None;
        }

        let len = request_body.len();
        let usable = len - 8;
        let varying_start = usize::min(16, usable);
        let varying_span = usable.saturating_sub(varying_start);
        let mut words = [0u64; 8];
        let word_count = words.len();

        for (idx, word) in words.iter_mut().enumerate() {
            let offset = if varying_span == 0 {
                usable
            } else if idx + 1 == word_count {
                usable
            } else {
                varying_start + ((idx * varying_span) / (word_count - 1))
            };
            *word = load_request_cache_word(request_body, offset);
        }

        Some(Self {
            len: len as u32,
            words,
        })
    }
}

#[inline(always)]
fn load_request_cache_word(bytes: &[u8], offset: usize) -> u64 {
    let start = usize::min(offset, bytes.len().saturating_sub(8));
    let mut word = [0u8; 8];
    word.copy_from_slice(&bytes[start..start + 8]);
    u64::from_le_bytes(word)
}

fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
    let sample_count = usize::min(count, TRAINING_SAMPLES);
    let mut sample = Vec::with_capacity(sample_count * DIM);

    if sample_count == 0 {
        return sample;
    }

    let step = count as f64 / sample_count as f64;
    let mut cursor = 0.0f64;

    for _ in 0..sample_count {
        let idx = usize::min(cursor as usize, count - 1);
        let start = idx * DIM;
        sample.extend_from_slice(&vectors[start..start + DIM]);
        cursor += step;
    }

    sample
}

